) AS (
  VALUES 
    (66::BIGINT, 'Es un curso muy sencillo. Todos los trabajos se hacen en clase por lo que el curso no toma mucho tiempo, los exámenes y trabajos semanales son en excel. El proyecto es largo pero como se trabaja casi semanalmente es demasiado sencillo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Inspirador', 'Muchos proyectos grupales']::TEXT[], '2025-12-15T00:00:00+00:00'::TIMESTAMPTZ, '737c8c2dc80a20c988abef54fbf4f32e40e9b576ee25185df69c6537a9595fe8'::TEXT, ARRAY[92]::BIGINT[]),
    (66::BIGINT, 'Trabajos semanales sencillos en los que el profe adjunta la solución para comparar resultados. Los exámenes son casi los mismos simulacros, así que si los hace le va a ir bien. Las explicaciones son muy concisas y las clases cortas. El proyecto es largo pero fácil. Excelente profe. Dele sin miedo.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2024-10-14T00:00:00+00:00'::TIMESTAMPTZ, '0e9ec939070845800a9b3842bc62e9066707bfae806659738f9dbd315cac4d7a'::TEXT, ARRAY[91]::BIGINT[]),
    (66::BIGINT, 'Hace trabajos en clase semanales sencillos, adjunta las respuestas para que uno compare con lo que obtuvo. El proyecto con un buen grupo de trabajo se hace muy fácil. Los exámenes son prácticamente los simulacros de examen que hace. Matricule sin miedo. Es super buena gente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2024-06-10T00:00:00+00:00'::TIMESTAMPTZ, 'a74932009d54e2503100bea374852dea27a2a10b879feba61963fa557d22c20d'::TEXT, ARRAY[92]::BIGINT[]),
    (66::BIGINT, 'Sus clases son muy cortas y todo es en excel, suele dejar trabajos sencillos en clase con ejercicios muy similares a los examenes. Califica súper suave el proyecto y es muy comprensivo. Además como el proyecto se inicia desde principios del semestre, al final casi ni se siente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo']::TEXT[], '2023-06-23T00:00:00+00:00'::TIMESTAMPTZ, '10f1459e46a90fc7d47795624d4b9a35b6be885c2e1a50f96a5da3c81f09982f'::TEXT, ARRAY[92]::BIGINT[]),
    (66::BIGINT, 'Excelente docente, sin duda alguna, matricule con el.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2023-06-01T00:00:00+00:00'::TIMESTAMPTZ, '54fca5b5cfb09d6fc05e1798a588824b33ea47dc9842f46570ed86c5f7cf11f0'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'El mejor profesor para este curso. Si usted hace los trabajos en clase que son super fáciles y atiende a las clases le va excelente en el curso y pega 100 en todo. Se aprende mucho. Las clases virtuales son cortas pero las dedica a hacer prácticas. El trabajo final tiene una guía excelente.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-10-25T00:00:00+00:00'::TIMESTAMPTZ, 'b2fdb1db9515dcf4729f9b567646a8e06db921cfb1dbe711a4e874d095b6ad54'::TEXT, ARRAY[91]::BIGINT[]),
    (66::BIGINT, 'Un gran profesor, el curso se pasa fácil, es entregar los avances del proyecto, también deja trabajos semanales pero se hacen como en una hora (y siempre los dá con la solución), los exámenes son fáciles porque el deja prácticas muy parecidas. Las consultas las atiende rápido y con buena actitud'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2022-06-12T00:00:00+00:00'::TIMESTAMPTZ, '0ba103dbfd639932557f3bdd5c93fddc07ef9b91426e3376bb726ae2864d047f'::TEXT, ARRAY[92]::BIGINT[]),
    (66::BIGINT, 'Las clases son cortas, el profe explica muy bien y es muy buena gente. Todas las semanas deja tareas, pero son muy fáciles y si uno las hace de fijo le va bien en los exámenes.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-11-18T00:00:00+00:00'::TIMESTAMPTZ, '7c701942a990a74d20bd71f071816ab52777cb77d0230c847b05973542805999'::TEXT, ARRAY[2367]::BIGINT[]),
    (66::BIGINT, 'Excelente como persona y profesor! Sabe explicar muy bien, lo hace resumido y fácil de entender. Ayuda a los estudiantes. Flexibles con los horarios y si hace todas las tareas, le va ir muy bien al examen! MATRICULEN CON ÉL!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-17T00:00:00+00:00'::TIMESTAMPTZ, '05f468c9a932f8f7cdb500a090b4db1f1b6d8d27348d40c3db628fc5416f6c36'::TEXT, ARRAY[2367]::BIGINT[]),
    (66::BIGINT, 'Muy fácil pasar el curso con él. Todo el semestre es entregar avances del proyecto y los exámenes los hace diferentes para los estudiantes pero son muy fáciles. Recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-14T00:00:00+00:00'::TIMESTAMPTZ, '3f011420bd0fe585e07a55fd5f1e68c59275fa1f5c21e2e0c9d7fc01a48e28f9'::TEXT, ARRAY[92]::BIGINT[]),
    (66::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-07-13T00:00:00+00:00'::TIMESTAMPTZ, 'f2ea94cdc8fb9e8057b009fa8bda614cff6dd046675c244ee4acc85e57fa6022'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'El profe es buenísimo. Es una persona muy amable y agradable. Todo lo enseña resumidamente pero muy fácil de entender. Para el proyecto ayuda mucho y explica todo bien. Las tareas son fáciles y los exámenes sencillos. 100% recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-12T00:00:00+00:00'::TIMESTAMPTZ, '663eaee4f12a7d5ff49845613536eef33f335788eed9515d8059fa471b18aeb2'::TEXT, ARRAY[91]::BIGINT[]),
    (66::BIGINT, 'El profe es el mejoooor, da las clases muy resumidas, siempre esta atento a tender dudas, responde rápido, es muy linda persona y volvería a llevarlo mil veces!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Tomaría su clase nuevamente']::TEXT[], '2021-06-11T00:00:00+00:00'::TIMESTAMPTZ, '951ffc56d60bd7814f1ad2b491dd1f8bbf2d91e5b8509b5d3802b54aa0df322e'::TEXT, ARRAY[91]::BIGINT[]),
    (66::BIGINT, 'Muy buen profe, da la clase a la velocidad adecuada, responde rápido e informa sobre lo que vamos a hacer tanto antes como después de la clase. Muy amable, abierto a consultas, si no entendió explica de nuevo sin problema. Flexible con los horarios y fechas de entrega. Si pueden matriculen con él!'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-05-13T00:00:00+00:00'::TIMESTAMPTZ, 'bb7d1623dd0109bc008ab29eb3e05f7a7861b37114b956b3f68150c9fb9f1488'::TEXT, ARRAY[92]::BIGINT[]),
    (66::BIGINT, 'En modalidad virtual se acopló bien, explica muy bien. Definitivamente volvería a llevar cursos con él'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-26T00:00:00+00:00'::TIMESTAMPTZ, 'e7659aec76fc6f0b04acc5034359e430bdc0a86d561b8409b865c4cea95b30f3'::TEXT, ARRAY[2358]::BIGINT[]),
    (66::BIGINT, 'Excelente profesor, se aclopó bien a la modalidad virtual, siempre está anuente a ayudar y es muy comprensivo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases largas', 'Tomaría su clase nuevamente']::TEXT[], '2021-01-25T00:00:00+00:00'::TIMESTAMPTZ, '1973d75c986118ce168d6a086b01e07167ff513e857e84b0471daf1d1f83e51d'::TEXT, ARRAY[2358]::BIGINT[]),
    (66::BIGINT, 'Él mejor profesor, es claro a la hora de explicar y las prácticas que da refuerzan mucho. MATRICULEN CON ÉL, super recomendado.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2021-01-23T00:00:00+00:00'::TIMESTAMPTZ, '4db6a082f4bc5b4b7dd169a740b763901261362a12e3f1756b9c2ee6c2d715a0'::TEXT, ARRAY[2358]::BIGINT[]),
    (66::BIGINT, 'Excelente profe, se centra mucho en que los estudiantes aprendan y entiendan la materia. Evalúa según lo visto en clase. Siempre está atento a las dudas y consulta. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-19T00:00:00+00:00'::TIMESTAMPTZ, 'ee7eefc340b3d7f04a12ca0becc2a02487c5cca25cf48e98b708fa2f8a04a299'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Excelente profesor, le gusta enseñar y no le importa repetir el tema las veces que sean necesarias. Ayuda a los estudiantes'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Asistencia obligatoria', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2019-12-18T00:00:00+00:00'::TIMESTAMPTZ, 'a3be50d7c1cea41d59ccd8c4670f191f7453e71d114f5b68c1e41f76dccdeb51'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Excelente como profesor y como persona'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-03-27T00:00:00+00:00'::TIMESTAMPTZ, 'e54045312a8f63497c3cadc0972f700adf40be54b1221bc9ec9b77cb711a4d40'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Excelente profesor, explica muy bien, las clases son divertidas, se practica mucho en clase. 100% Recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY['Brinda apoyo', 'Clases excelentes']::TEXT[], '2018-01-12T00:00:00+00:00'::TIMESTAMPTZ, 'ad8b9657f9c311f5357102ec233cc63f76a30cb2cbdd51bf84b925b9a434cde9'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Es una excelente y muy considerada persona. Explica muy bien y ayuda mucho a sus estudiantes. Definitivamente se aprende bastante con él y la clase se vuelve fácil. Es un 10 como persona y como profesor. Súper recomendado.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'c773737201e7034a5f6c2b60a70e0ebe8464886379e267de9c400a39a1c3bebb'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Muy clara la materia y el profe es super buena gente ademas de que es fácil pasar con el.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Tomaría su clase nuevamente']::TEXT[], '2017-11-09T00:00:00+00:00'::TIMESTAMPTZ, 'e82a6f32132d2b82192949ce1981d65d517b0f7b529a91ce3e4630aab27ebc21'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Él explica de la mejor manera. Si al final no entendiste, te lo vuelve a explicar paso por paso. Definitivamente un excelente profesor.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Tomaría su clase nuevamente']::TEXT[], '2017-09-02T00:00:00+00:00'::TIMESTAMPTZ, 'e85570691138c6132433bfb786a2a12e904e0b3c6fe8f6e223a687fb1c126196'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Totalmente recomendado'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Pocos exámenes', 'Brinda apoyo']::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, '62577c1e4799e7dee6b418d364f1146d58309eed82eb23d357477d5f4fff9f4e'::TEXT, ARRAY[1707]::BIGINT[]),
    (66::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-06T00:00:00+00:00'::TIMESTAMPTZ, 'a917fda1fe69838e6a8094e242094197f58f864671f500b751c2c795f435208f'::TEXT, ARRAY[1707]::BIGINT[]),
    (66::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'aab8103a1bb3c8aeb0dd6b4bdc8b84b53b5fd5c42a6027d08ce0eb0687822e64'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Muy buen profe, muy llevadero y es fácil la materia con el!'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-01-21T00:00:00+00:00'::TIMESTAMPTZ, '069398b1b636afa9e64b063067f31ce477bab4ed9e86969f7314954bcb9f63f9'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'El mejor profe'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF('95','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-07-20T00:00:00+00:00'::TIMESTAMPTZ, 'd3b1cf14bec9e9373d86caf25226a48b1ca209e0e60df6dae594037a06e86fde'::TEXT, ARRAY[2361]::BIGINT[]),
    (66::BIGINT, 'Excelente profesor!'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2015-01-07T00:00:00+00:00'::TIMESTAMPTZ, '6ffb0505ff1681cb9e33f4f8d732cd0c34b4860173f97141dce707bc73a90020'::TEXT, ARRAY[91]::BIGINT[]),
    (66::BIGINT, 'Ninguno'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2014-11-30T00:00:00+00:00'::TIMESTAMPTZ, '49f9f7a939da605e027aefc7277406139edaf4e865c4f73f23a30573f0ea97e5'::TEXT, ARRAY[1707]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
